import Mathlib

-- Define the mechanism design framework
variable {I : Type*} [Fintype I] [DecidableEq I]
variable {Θ : I → Type*} {X : Type*}

-- Lower contour set: outcomes weakly dispreferred to x under type θ_i
def LowerContourSet (u : X → ℝ) (x : X) : Set X :=
  {y : X | u y ≤ u x}

-- Social choice function

import Mathlib

variable {Outcome TypeI TypeOthers : Type*}

def DSIC (f : TypeI → TypeOthers → Outcome) (u : Outcome → TypeI → ℝ) : Prop :=
  ∀ (θ_i θ_i' : TypeI) (θ_others : TypeOthers),
    u (f θ_i θ_others) θ_i ≥ u (f θ_i' θ_others) θ_i

import Mathlib

def productExcept {I : ℕ} (Θ : Fin I → Type*) (i : Fin I) : Type _ :=
  (j : { k : Fin I // k ≠ i }) → Θ j.val

import Mathlib

variable {X : Type*} [DecidableEq X] {I : Type*} {Θ : I → Type*}

def StrictRationalPrefs (X : Type*) : Set (X → X → Prop) :=
  {R | (∀ x y, R x y ∨ R y x) ∧
       (∀ x y z, R x y → R y z → R x z) ∧
       (∀ x y, R x y → R y x → x = y)}

import Mathlib

variable {I : Type*} [Fintype I] [DecidableEq I]
variable {Θ : I → Type*} [∀ i, Fintype (Θ i)] [∀ i, DecidableEq (Θ i)]
variable {X : Type*}

abbrev SocialChoiceFunction (Θ : I → Type*) (X : Type*) := (∀ i, Θ i) → X

def F_BIC (isBIC : SocialChoiceFunction Θ X → Prop) : Set (SocialChoiceFunction Θ X) :=
  {f | isBIC f}

import Mathlib

variable {Outcome Mechanism Equilibrium : Type*}

def WeaklyImplements (equilOf : Mechanism → Set Equilibrium)
    (outcome : Mechanism → Equilibrium → Outcome)
    (goal : Set Outcome) (m : Mechanism) : Prop :=
  ∃ e ∈ equilOf m, outcome m e ∈ goal
